import { connection } from 'next/server';

export default async function Home() {
  await connection();
  const timestamp = new Date();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>
        Current server time:{' '}
        <time dateTime={timestamp.toISOString()}>
          {timestamp.toLocaleString()}
        </time>
      </p>
    </main>
  );
}

